settings.custom_liquid:
{%- comment -%}
  Custom Liquid block — Produktvarianter
  Læser fra metafelt: custom.variant_products (list.product_reference)
  Ingen manuel opsætning — virker automatisk når metafeltet er sat.
{%- endcomment -%}

{%- comment -%} ═══ KONFIGURATION ═══ {%- endcomment -%}
{%- assign heading       = 'Størrelse' -%}
{%- assign show_price    = true -%}
{%- assign hint_text     = '' -%}
{%- assign hint_url      = '' -%}
{%- comment -%} ════════════════════ {%- endcomment -%}

{{ 'yy-variations.css' | asset_url | stylesheet_tag }}

{%- assign variant_products = product.metafields.custom.variant_products.value -%}

{%- if variant_products != blank and variant_products.size > 0 -%}

{%- assign uid = block.id | default: product.id -%}

<div class="yy-variations" id="yy-var-{{ uid }}">
  <div class="yy-vargroup">

    <div class="yy-vargroup__head">
      <span class="yy-vargroup__label">{{ heading }}</span>
      <span class="yy-vargroup__value" id="yy-var-val-{{ uid }}">
        {%- for vp in variant_products -%}
          {%- if vp.id == product.id -%}{{ vp.title }}{%- endif -%}
        {%- endfor -%}
      </span>
      {%- if hint_text != blank -%}
        <a href="{{ hint_url | default: '#' }}" class="yy-vargroup__hint">{{ hint_text }}</a>
      {%- endif -%}
    </div>

    <div class="yy-vargroup__grid">
      {%- for vp in variant_products -%}
        {%- assign vv = vp.selected_or_first_available_variant -%}
        {%- assign is_current = false -%}
        {%- if vp.id == product.id -%}{%- assign is_current = true -%}{%- endif -%}
        {%- assign is_soldout = false -%}
        {%- unless vv.available -%}{%- assign is_soldout = true -%}{%- endunless -%}

        <label class="yy-varbox{% if is_soldout %} yy-varbox--disabled{% endif %}">
          <input
            type="radio"
            name="yy-var-{{ uid }}"
            class="yy-varbox__input"
            value="{{ vp.url }}"
            data-label="{{ vp.title | escape }}"
            {% if is_current %}checked{% endif %}
            {% if is_soldout %}disabled{% endif %}
          >
          <span class="yy-varbox__media">
            {%- if vp.featured_image -%}
              <img
                src="{{ vp.featured_image | image_url: width: 400 }}"
                alt="{{ vp.title | escape }}"
                width="200"
                height="200"
                loading="lazy"
              >
            {%- endif -%}
            {%- if is_soldout -%}
              <span class="yy-varbox__badge yy-varbox__badge--soldout">Udsolgt</span>
            {%- elsif vv.compare_at_price > vv.price -%}
              {%- assign save_pct = vv.compare_at_price | minus: vv.price | times: 100 | divided_by: vv.compare_at_price -%}
              <span class="yy-varbox__badge yy-varbox__badge--sale">−{{ save_pct }}%</span>
            {%- endif -%}
          </span>
          <span class="yy-varbox__body">
            <span class="yy-varbox__name">{{ vp.title | escape }}</span>
            {%- if show_price -%}
              <span class="yy-varbox__meta">
                {%- if vv.compare_at_price > vv.price -%}
                  <span class="yy-varbox__meta--strike">{{ vv.compare_at_price | money_without_trailing_zeros }}</span>
                {%- endif -%}
                {{ vv.price | money_without_trailing_zeros }}
              </span>
            {%- endif -%}
          </span>
          <span class="yy-varbox__check" aria-hidden="true"></span>
        </label>
      {%- endfor -%}
    </div>

  </div>
</div>

<script>
(function () {
  var wrap   = document.getElementById('yy-var-{{ uid }}');
  var valEl  = document.getElementById('yy-var-val-{{ uid }}');
  if (!wrap) return;

  wrap.addEventListener('change', function (e) {
    var input = e.target;
    if (!input.classList.contains('yy-varbox__input') || input.disabled) return;
    if (valEl) valEl.textContent = input.dataset.label || '';
    setTimeout(function () { window.location.href = input.value; }, 100);
  });
})();
</script>

{%- endif -%}

{%- comment -%}
  Custom Liquid block — Bundle + Ofte købt sammen
  Metafelter der skal oprettes på produktet:
    custom.bundle_product        → Type: Produkt (enkelt reference)
    custom.crosssell_products    → Type: Liste af produkter
{%- endcomment -%}

{%- comment -%} ═══ KONFIGURATION — rediger her ═══ {%- endcomment -%}
{%- assign bundle_eyebrow      = 'KØB I SÆT' -%}
{%- assign bundle_title        = 'Spar [[discount]]% når du tager hele sættet' -%}
{%- assign bundle_subtitle     = '' -%}
{%- assign bundle_button_text  = 'TILFØJ SÆT' -%}
{%- assign fbt_heading         = 'OFTE KØBT SAMMEN MED' -%}
{%- assign fbt_button_text     = '+ Tilføj' -%}
{%- comment -%} ═══════════════════════════════════ {%- endcomment -%}

{%- liquid
  assign bundle_product  = product.metafields.custom.bundle_product.value
  assign fbt_products    = product.metafields.custom.crosssell_products.value
  assign current_variant = product.selected_or_first_available_variant

  if bundle_product != blank
    assign bundle_variant = bundle_product.selected_or_first_available_variant

    if bundle_variant.compare_at_price > bundle_variant.price
      assign bundle_compare = bundle_variant.compare_at_price
    else
      assign bundle_compare = bundle_variant.price
    endif

    assign bundle_price    = bundle_variant.price
    assign discount_amount = bundle_compare | minus: bundle_price

    if bundle_compare > 0
      assign discount_pct = discount_amount | times: 100 | divided_by: bundle_compare
    else
      assign discount_pct = 0
    endif

    assign show_bundle = true
  else
    assign show_bundle = false
  endif

  assign show_fbt = false
  if fbt_products != blank and fbt_products.size > 0
    assign show_fbt = true
  endif
-%}

{%- if show_bundle or show_fbt -%}

{%- assign uid = block.id | default: product.id -%}
<div class="yy-wrap" id="yy-b-{{ uid }}">

  {%- if show_bundle -%}
  <div class="yy-bundle">
    {%- if discount_pct > 0 -%}<span class="yy-bundle__badge">−{{ discount_pct }}%</span>{%- endif -%}

    <a href="{{ bundle_product.url }}" class="yy-bundle__img-link">
      <div class="yy-bundle__img"
        {%- if bundle_product.featured_image %} style="background-image:url('{{ bundle_product.featured_image | image_url: width: 200 }}')"{% endif %}></div>
    </a>

    <div class="yy-bundle__body">
      <div>
        <div class="yy-bundle__eyebrow">{{ bundle_eyebrow }}</div>
        <a href="{{ bundle_product.url }}" class="yy-bundle__title-link">
          <h3 class="yy-bundle__title">{{ bundle_title | replace: '[[discount]]', discount_pct }}</h3>
        </a>
        <p class="yy-bundle__sub">
          {%- if bundle_subtitle != blank -%}
            {{ bundle_subtitle }}
          {%- else -%}
            {{ bundle_product.title }}
          {%- endif -%}
        </p>
      </div>

      <div class="yy-bundle__footer">
        <div>
          <div class="yy-price">
            <span class="yy-price__now">{{ bundle_price | money }}</span>
            {%- if discount_amount > 0 -%}
            <span class="yy-price__was">{{ bundle_compare | money }}</span>
            {%- endif -%}
          </div>
          {%- if discount_amount > 0 -%}
          <div class="yy-price__save">Du sparer {{ discount_amount | money }}</div>
          {%- endif -%}
        </div>
        <button
          type="button"
          class="yy-btn-primary"
          data-bundle-btn
          data-v1="{{ bundle_variant.id }}"
        >{{ bundle_button_text }}</button>
      </div>
    </div>
  </div>
  {%- endif -%}

  {%- if show_fbt -%}
  <div class="yy-fbt">
    <div class="yy-fbt__heading">{{ fbt_heading }}</div>
    <ul class="yy-fbt__list">
      {%- for p in fbt_products -%}
        {%- assign fv = p.selected_or_first_available_variant -%}
        <li class="yy-fbt__item">
          <a href="{{ p.url }}" class="yy-fbt__link">
            <div class="yy-fbt__thumb"
              {%- if p.featured_image %} style="background-image:url('{{ p.featured_image | image_url: width: 104 }}')"{% endif %}></div>
            <div>
              <p class="yy-fbt__name">{{ p.title }}</p>
              <div class="yy-fbt__price">{{ fv.price | money }}</div>
            </div>
          </a>
          <button type="button" class="yy-btn-ghost" data-fbt-btn data-vid="{{ fv.id }}">
            {{ fbt_button_text }}
          </button>
        </li>
      {%- endfor -%}
    </ul>
  </div>
  {%- endif -%}

</div>

<style>
  #yy-b-{{ uid }} {
    --yy-green: #5b8a48;
    --yy-dark:  #1a1a1a;
    --yy-gray:  #6b6b6b;
    --yy-line:  #ececec;
    display: flex;
    flex-direction: column;
    gap: 20px;
    font-family: -apple-system, BlinkMacSystemFont, 'Inter', sans-serif;
    -webkit-font-smoothing: antialiased;
    color: var(--yy-dark);
  }
  #yy-b-{{ uid }} *, #yy-b-{{ uid }} *::before, #yy-b-{{ uid }} *::after { box-sizing: border-box; }

  /* Bundle card */
  #yy-b-{{ uid }} .yy-bundle {
    position: relative;
    border: 1.5px solid var(--yy-dark);
    border-radius: 12px;
    padding: 16px;
    background: #fff;
    display: grid;
    grid-template-columns: 100px 1fr;
    gap: 16px;
    align-items: stretch;
  }
  #yy-b-{{ uid }} .yy-bundle__badge {
    position: absolute;
    top: 12px;
    right: 12px;
    background: var(--yy-green);
    color: #fff;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.06em;
    padding: 4px 9px;
    border-radius: 999px;
    line-height: 1;
  }
  #yy-b-{{ uid }} .yy-bundle__img-link {
    display: block;
    flex-shrink: 0;
  }
  #yy-b-{{ uid }} .yy-bundle__img {
    width: 100px;
    height: 100px;
    border-radius: 8px;
    background-color: #f0ede7;
    background-size: cover;
    background-position: center;
  }
  #yy-b-{{ uid }} .yy-bundle__img-link:hover .yy-bundle__img {
    opacity: 0.85;
  }
  #yy-b-{{ uid }} .yy-bundle__title-link {
    text-decoration: none;
    color: inherit;
  }
  #yy-b-{{ uid }} .yy-bundle__title-link:hover .yy-bundle__title {
    text-decoration: underline;
  }
  #yy-b-{{ uid }} .yy-bundle__body {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }
  #yy-b-{{ uid }} .yy-bundle__eyebrow {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.14em;
    color: var(--yy-green);
    margin: 0 0 5px;
  }
  #yy-b-{{ uid }} .yy-bundle__title {
    font-size: 15px;
    font-weight: 700;
    letter-spacing: -0.01em;
    line-height: 1.3;
    margin: 0 0 5px;
  }
  #yy-b-{{ uid }} .yy-bundle__sub {
    font-size: 12px;
    color: var(--yy-gray);
    line-height: 1.45;
    margin: 0;
  }
  #yy-b-{{ uid }} .yy-bundle__footer {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-top: 12px;
    gap: 10px;
    flex-wrap: wrap;
  }
  #yy-b-{{ uid }} .yy-price { display: flex; align-items: baseline; gap: 7px; flex-wrap: wrap; }
  #yy-b-{{ uid }} .yy-price__now { font-size: 18px; font-weight: 700; }
  #yy-b-{{ uid }} .yy-price__was { font-size: 12px; color: var(--yy-gray); text-decoration: line-through; }
  #yy-b-{{ uid }} .yy-price__save { font-size: 11px; color: var(--yy-green); font-weight: 600; margin-top: 2px; }

  /* Buttons */
  #yy-b-{{ uid }} .yy-btn-primary {
    background: var(--yy-dark);
    color: #fff;
    border: none;
    border-radius: 999px;
    padding: 10px 18px;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.05em;
    cursor: pointer;
    white-space: nowrap;
    font-family: inherit;
    transition: background 0.15s;
  }
  #yy-b-{{ uid }} .yy-btn-primary:hover:not(:disabled) { background: #333; }
  #yy-b-{{ uid }} .yy-btn-primary:disabled { opacity: 0.6; cursor: default; }

  /* Often bought together */
  #yy-b-{{ uid }} .yy-fbt__heading {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.14em;
    color: var(--yy-gray);
    margin: 0 0 10px;
  }
  #yy-b-{{ uid }} .yy-fbt__list { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 8px; }
  #yy-b-{{ uid }} .yy-fbt__item {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 8px;
    border: 1px solid var(--yy-line);
    border-radius: 8px;
  }
  #yy-b-{{ uid }} .yy-fbt__link {
    display: flex;
    align-items: center;
    gap: 12px;
    flex: 1;
    min-width: 0;
    text-decoration: none;
    color: inherit;
  }
  #yy-b-{{ uid }} .yy-fbt__link:hover .yy-fbt__name {
    text-decoration: underline;
  }
  #yy-b-{{ uid }} .yy-fbt__thumb {
    width: 52px; height: 52px;
    border-radius: 6px;
    background-color: #f0ede7;
    background-size: cover;
    background-position: center;
    flex-shrink: 0;
  }
  #yy-b-{{ uid }} .yy-fbt__name { font-size: 13px; font-weight: 500; line-height: 1.3; margin: 0; }
  #yy-b-{{ uid }} .yy-fbt__price { font-size: 12px; font-weight: 600; margin-top: 2px; }
  #yy-b-{{ uid }} .yy-btn-ghost {
    background: #fff;
    color: var(--yy-dark);
    border: 1.5px solid var(--yy-dark);
    border-radius: 999px;
    padding: 6px 12px;
    font-size: 11px;
    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
    font-family: inherit;
    transition: background 0.15s, color 0.15s;
  }
  #yy-b-{{ uid }} .yy-btn-ghost:hover:not(:disabled) { background: var(--yy-dark); color: #fff; }
  #yy-b-{{ uid }} .yy-btn-ghost:disabled { opacity: 0.6; cursor: default; }

  @media (max-width: 480px) {
    #yy-b-{{ uid }} .yy-bundle { grid-template-columns: 1fr; }
  }
</style>

<script>
(function () {
  var wrap = document.getElementById('yy-b-{{ uid }}');
  if (!wrap) return;
  var root = (window.Shopify && window.Shopify.routes && window.Shopify.routes.root) || '/';

  function addToCart(items) {
    return fetch(root + 'cart/add.js', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify({ items: items })
    }).then(function (res) {
      if (!res.ok) return res.json().then(function (e) { throw new Error(e.description || 'Fejl'); });
      return res.json();
    });
  }

  function refreshCart() {
    document.dispatchEvent(new CustomEvent('cart:refresh', { bubbles: true }));
    fetch(root + 'cart.js').then(function (r) { return r.json(); }).then(function (cart) {
      document.dispatchEvent(new CustomEvent('cart:updated', { bubbles: true, detail: { cart: cart } }));
    });
  }

  function withFeedback(btn, label, fn) {
    var orig = btn.textContent.trim();
    btn.disabled = true;
    btn.textContent = '…';
    fn().then(function () {
      btn.textContent = label;
      refreshCart();
    }).catch(function (e) {
      btn.textContent = e.message || 'Fejl';
    }).finally(function () {
      setTimeout(function () { btn.textContent = orig; btn.disabled = false; }, 2200);
    });
  }

  var bb = wrap.querySelector('[data-bundle-btn]');
  if (bb) {
    bb.addEventListener('click', function () {
      withFeedback(bb, '✓ Tilføjet!', function () {
        return addToCart([{ id: Number(bb.dataset.v1), quantity: 1 }]);
      });
    });
  }

  wrap.querySelectorAll('[data-fbt-btn]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      withFeedback(btn, '✓ Tilføjet', function () {
        return addToCart([{ id: Number(btn.dataset.vid), quantity: 1 }]);
      });
    });
  });
})();
</script>

{%- endif -%}
